class Heap {
  constructor(before) {
    this.items = []
    this.before = before
  }

  get size() {
    return this.items.length
  }

  peek() {
    return this.items[0]
  }

  push(item) {
    const a = this.items
    a.push(item)
    let i = a.length - 1
    while (i > 0) {
      const parent = (i - 1) >> 1
      if (!this.before(a[i], a[parent])) break
      ;[a[i], a[parent]] = [a[parent], a[i]]
      i = parent
    }
  }

  pop() {
    const a = this.items
    const top = a[0]
    const last = a.pop()
    if (a.length) {
      a[0] = last
      let i = 0
      for (;;) {
        const l = 2 * i + 1
        const r = l + 1
        let m = i
        if (l < a.length && this.before(a[l], a[m])) m = l
        if (r < a.length && this.before(a[r], a[m])) m = r
        if (m === i) break
        ;[a[i], a[m]] = [a[m], a[i]]
        i = m
      }
    }
    return top
  }
}

function runningMedians(nums) {
  const low = new Heap((a, b) => a > b)
  const high = new Heap((a, b) => a < b)
  return nums.map(num => {
    if (!low.size || num <= low.peek()) low.push(num)
    else high.push(num)
    if (low.size > high.size + 1) high.push(low.pop())
    else if (high.size > low.size) low.push(high.pop())
    return low.size > high.size ? low.peek() : (low.peek() + high.peek()) / 2
  })
}

